{
  "name": "prisma-3d-studio",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Prisma 3D — estúdio de animação 3D no navegador",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.5"
  }
}

export const PROJECT_VERSION = 1;

export const EASINGS = {
  linear: (p) => p,
  easeIn: (p) => p * p * p,
  easeOut: (p) => 1 - Math.pow(1 - p, 3),
  easeInOut: (p) => (p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2),
  backOut: (p) => {
    const c1 = 1.70158;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(p - 1, 3) + c1 * Math.pow(p - 1, 2);
  },
  bounceOut: (p) => {
    const n1 = 7.5625;
    const d1 = 2.75;
    if (p < 1 / d1) return n1 * p * p;
    if (p < 2 / d1) return n1 * (p -= 1.5 / d1) * p + 0.75;
    if (p < 2.5 / d1) return n1 * (p -= 2.25 / d1) * p + 0.9375;
    return n1 * (p -= 2.625 / d1) * p + 0.984375;
  },
  elasticOut: (p) => {
    if (p === 0 || p === 1) return p;
    return Math.pow(2, -10 * p) * Math.sin((p * 10 - 0.75) * ((2 * Math.PI) / 3)) + 1;
  },
  step: (p) => (p < 1 ? 0 : 1),
};

export const EASE_OPTIONS = [
  ['linear', 'Linear'],
  ['easeIn', 'Acelerar'],
  ['easeOut', 'Desacelerar'],
  ['easeInOut', 'Suave'],
  ['backOut', 'Com retorno'],
  ['bounceOut', 'Quique'],
  ['elasticOut', 'Elástico'],
  ['step', 'Degrau'],
];

export const TRACK_META = {
  position: { label: 'Posição', color: '#67e8f9' },
  rotation: { label: 'Rotação', color: '#a78bfa' },
  scale: { label: 'Escala', color: '#fbbf24' },
  target: { label: 'Alvo', color: '#fb7185' },
};

export const PRIMITIVE_DEFS = [
  { id: 'box', label: 'Cubo', icon: 'cube', color: '#8b5cf6' },
  { id: 'sphere', label: 'Esfera', icon: 'sphere', color: '#22d3ee' },
  { id: 'cylinder', label: 'Cilindro', icon: 'cylinder', color: '#34d399' },
  { id: 'cone', label: 'Cone', icon: 'cone', color: '#fbbf24' },
  { id: 'torus', label: 'Toro', icon: 'torus', color: '#fb7185' },
  { id: 'plane', label: 'Plano', icon: 'plane', color: '#94a3b8' },
];

export const PRESET_DEFS = [
  { id: 'spin', label: 'Girar 360°', icon: 'rotate' },
  { id: 'float', label: 'Flutuar', icon: 'wave' },
  { id: 'bounce', label: 'Quicar', icon: 'arrowUp' },
  { id: 'pulse', label: 'Pulsar', icon: 'target' },
  { id: 'orbit', label: 'Orbitar', icon: 'orbit' },
  { id: 'entrance', label: 'Entrada', icon: 'sparkles' },
  { id: 'swing', label: 'Balançar', icon: 'rotate' },
  { id: 'shake', label: 'Tremer', icon: 'move' },
];

let counter = 0;

export function uid(prefix = 'obj') {
  counter += 1;
  return `${prefix}_${Date.now().toString(36)}${counter.toString(36)}`;
}

export const roundTime = (t, precision = 3) => {
  const f = 10 ** precision;
  return Math.round(t * f) / f;
};

export function clamp(v, min, max) {
  return Math.min(max, Math.max(min, v));
}

export function uniqueName(objects, base, excludeId = null) {
  const used = new Set(objects.filter((o) => o.id !== excludeId).map((o) => o.name));
  if (!used.has(base)) return base;
  let i = 2;
  while (used.has(`${base} ${i}`)) i += 1;
  return `${base} ${i}`;
}

export function defaultMaterial(color = '#8b5cf6') {
  return {
    color,
    metalness: 0.35,
    roughness: 0.3,
    emissive: '#000000',
    emissiveIntensity: 0,
    opacity: 1,
    wireframe: false,
    flatShading: false,
  };
}

export function createTransform(position = [0, 1, 0]) {
  return {
    position: [...position],
    rotation: [0, 0, 0],
    scale: [1, 1, 1],
  };
}

export function emptyKeyframes() {
  return { position: [], rotation: [], scale: [], target: [] };
}

export function createPrimitive(type, project, options = {}) {
  const def = PRIMITIVE_DEFS.find((p) => p.id === type) || PRIMITIVE_DEFS[0];
  const y = type === 'plane' ? 0.01 : type === 'torus' ? 1.2 : 1;
  const obj = {
    id: uid('mesh'),
    name: uniqueName(project.objects, options.name || def.label),
    kind: 'mesh',
    parentId: null,
    visible: true,
    castShadow: type !== 'plane',
    receiveShadow: true,
    transform: createTransform(options.position || [options.x ?? 0, y, options.z ?? 0]),
    keyframes: emptyKeyframes(),
    geometry: { type },
    material: defaultMaterial(options.color || def.color),
    light: null,
    clip: null,
    asset: null,
  };
  if (type === 'plane') {
    obj.transform.rotation = [-Math.PI / 2, 0, 0];
    obj.transform.position = [0, 0.01, 0];
  }
  return obj;
}

export function createGroup(project, options = {}) {
  return {
    id: uid('grp'),
    name: uniqueName(project.objects, options.name || 'Grupo'),
    kind: 'group',
    parentId: options.parentId || null,
    visible: true,
    castShadow: false,
    receiveShadow: false,
    transform: createTransform(options.position || [0, 0, 0]),
    keyframes: emptyKeyframes(),
    geometry: null,
    material: null,
    light: null,
    clip: null,
    asset: null,
  };
}

export function createLight(type, project, options = {}) {
  const presets = {
    directional: {
      name: 'Luz direcional',
      color: '#fff1d6',
      intensity: 3,
      distance: 0,
      angle: Math.PI / 5,
      penumbra: 0.4,
      position: [5, 8, 4],
    },
    point: {
      name: 'Luz pontual',
      color: '#7c5cff',
      intensity: 40,
      distance: 0,
      angle: Math.PI / 4,
      penumbra: 0.5,
      position: [-4, 2.5, -3],
    },
    spot: {
      name: 'Spot',
      color: '#22d3ee',
      intensity: 90,
      distance: 30,
      angle: Math.PI / 6,
      penumbra: 0.55,
      position: [4, 6, -4],
    },
  };
  const p = presets[type] || presets.point;
  return {
    id: uid('lgt'),
    name: uniqueName(project.objects, options.name || p.name),
    kind: 'light',
    parentId: null,
    visible: true,
    castShadow: type === 'directional' || type === 'spot',
    receiveShadow: false,
    transform: createTransform(options.position || p.position),
    keyframes: emptyKeyframes(),
    geometry: null,
    material: null,
    light: {
      type,
      color: options.color || p.color,
      intensity: options.intensity ?? p.intensity,
      distance: options.distance ?? p.distance,
      angle: options.angle ?? p.angle,
      penumbra: options.penumbra ?? p.penumbra,
    },
    clip: null,
    asset: null,
  };
}

export function createCamera(project, options = {}) {
  return {
    id: uid('cam'),
    name: uniqueName(project.objects, options.name || 'Câmera'),
    kind: 'camera',
    parentId: null,
    visible: true,
    castShadow: false,
    receiveShadow: false,
    transform: createTransform(options.position || [6.6, 4.4, 9.2]),
    target: options.target ? [...options.target] : [0, 1.2, 0],
    fov: options.fov || 45,
    keyframes: emptyKeyframes(),
    geometry: null,
    material: null,
    light: null,
    clip: null,
    asset: null,
  };
}

export function baseProject(name = 'Cena sem título') {
  return {
    version: PROJECT_VERSION,
    name,
    settings: {
      duration: 6,
      fps: 30,
      loop: true,
      background: '#060913',
      grid: true,
      shadows: true,
      fog: true,
      environment: 0.55,
    },
    camera: {
      position: [7.2, 4.8, 9.8],
      target: [0, 1.3, 0],
    },
    objects: [],
    nextNumber: 1,
  };
}

function addDefaultLights(project, mood = 'neon') {
  if (mood === 'neon') {
    project.objects.push(
      createLight('directional', project, {
        name: 'Sol quente',
        position: [5.5, 8.5, 4.5],
        color: '#ffedd5',
        intensity: 3.2,
      }),
      createLight('point', project, {
        name: 'Luz violeta',
        position: [-4.2, 2.6, -3.2],
        color: '#8b5cf6',
        intensity: 55,
      }),
      createLight('spot', project, {
        name: 'Rim ciano',
        position: [4.5, 6.2, -4.5],
        color: '#22d3ee',
        intensity: 120,
      }),
    );
  } else if (mood === 'studio') {
    project.objects.push(
      createLight('directional', project, {
        name: 'Softbox',
        position: [4.5, 7.5, 5.5],
        color: '#fff7ed',
        intensity: 3.6,
      }),
      createLight('point', project, {
        name: 'Preenchimento',
        position: [-4, 2.2, 3],
        color: '#bfdbfe',
        intensity: 24,
      }),
      createLight('spot', project, {
        name: 'Contraluz',
        position: [-2.5, 5.5, -4.5],
        color: '#fda4af',
        intensity: 80,
      }),
    );
  } else {
    project.objects.push(
      createLight('directional', project, {
        position: [4, 7, 4],
      }),
      createLight('point', project, {
        position: [-3, 2, -2],
      }),
    );
  }
}

function orbitKeys(radius, center, phase, duration, steps = 8, y = 0) {
  const keys = [];
  for (let i = 0; i <= steps; i += 1) {
    const a = phase + (i / steps) * Math.PI * 2;
    keys.push({
      t: roundTime((i / steps) * duration),
      v: [center[0] + Math.cos(a) * radius, y, center[2] + Math.sin(a) * radius],
      ease: 'linear',
    });
  }
  return keys;
}

export function createTemplate(templateId = 'neon') {
  const project = baseProject();
  project.objects.push(createCamera(project, { name: 'Câmera', position: [6.6, 4.4, 9.2], target: [0, 1.25, 0] }));

  if (templateId === 'empty') {
    project.name = 'Cena vazia';
    project.settings.background = '#080b12';
    project.settings.environment = 0.4;
    project.camera = { position: [5.5, 3.8, 7], target: [0, 1, 0] };
    addDefaultLights(project, 'plain');
    return project;
  }

  if (templateId === 'showcase') {
    project.name = 'Vitrine';
    project.settings.background = '#08070d';
    project.settings.environment = 0.9;
    project.settings.duration = 8;
    project.camera = { position: [5.8, 3.6, 7.8], target: [0, 1.05, 0] };
    const camera = project.objects[0];
    camera.transform.position = [5.8, 3.4, 7.6];
    camera.target = [0, 1.05, 0];
    camera.keyframes.position = [
      { t: 0, v: [5.9, 3.4, 7.7], ease: 'easeInOut' },
      { t: 4, v: [4.2, 2.7, 6.1], ease: 'easeInOut' },
      { t: 8, v: [5.9, 3.4, 7.7], ease: 'easeInOut' },
    ];
    camera.keyframes.target = [
      { t: 0, v: [0, 1.05, 0], ease: 'easeInOut' },
      { t: 4, v: [0, 1.2, 0], ease: 'easeInOut' },
      { t: 8, v: [0, 1.05, 0], ease: 'easeInOut' },
    ];
    addDefaultLights(project, 'studio');

    const platform = createPrimitive('cylinder', project, {
      name: 'Pedestal',
      position: [0, 0.11, 0],
      color: '#121522',
    });
    platform.transform.scale = [2.4, 0.22, 2.4];
    platform.material.metalness = 0.65;
    platform.material.roughness = 0.3;
    platform.castShadow = true;
    project.objects.push(platform);

    const group = createGroup(project, { name: 'Produto', position: [0, 0, 0] });
    group.keyframes.rotation = [
      { t: 0, v: [0, 0, 0], ease: 'linear' },
      { t: 8, v: [0, Math.PI * 2, 0], ease: 'linear' },
    ];
    project.objects.push(group);

    const body = createPrimitive('cylinder', project, {
      name: 'Frasco',
      position: [0, 0.95, 0],
      color: '#f2e9da',
    });
    body.parentId = group.id;
    body.transform.scale = [0.62, 1.25, 0.62];
    body.material.metalness = 0.18;
    body.material.roughness = 0.28;
    project.objects.push(body);

    const cap = createPrimitive('cylinder', project, {
      name: 'Tampa',
      position: [0, 2.1, 0],
      color: '#171b29',
    });
    cap.parentId = group.id;
    cap.transform.scale = [0.46, 0.32, 0.46];
    cap.material.metalness = 0.9;
    cap.material.roughness = 0.2;
    project.objects.push(cap);

    const ring = createPrimitive('torus', project, {
      name: 'Anel dourado',
      position: [0, 1.42, 0],
      color: '#f5c76a',
    });
    ring.parentId = group.id;
    ring.transform.rotation = [Math.PI / 2, 0, 0];
    ring.transform.scale = [1.02, 1.02, 1.02];
    ring.material.metalness = 1;
    ring.material.roughness = 0.16;
    project.objects.push(ring);

    return project;
  }

  // Padrão: Órbita Neon
  project.name = 'Órbita Neon';
  project.settings.duration = 6;
  project.settings.background = '#05070f';
  project.settings.environment = 0.6;
  const camera = project.objects[0];
  camera.keyframes.position = [
    { t: 0, v: [6.6, 4.4, 9.2], ease: 'easeInOut' },
    { t: 3, v: [5.6, 3.8, 8], ease: 'easeInOut' },
    { t: 6, v: [6.6, 4.4, 9.2], ease: 'easeInOut' },
  ];
  addDefaultLights(project, 'neon');

  const platform = createPrimitive('cylinder', project, {
    name: 'Palco',
    position: [0, 0.09, 0],
    color: '#0b1220',
  });
  platform.transform.scale = [3.15, 0.18, 3.15];
  platform.material.metalness = 0.72;
  platform.material.roughness = 0.3;
  platform.material.emissive = '#0b2d3b';
  platform.material.emissiveIntensity = 0.18;
  platform.castShadow = false;
  project.objects.push(platform);

  const nucleus = createPrimitive('sphere', project, {
    name: 'Núcleo',
    position: [0, 1.62, 0],
    color: '#8b5cf6',
  });
  nucleus.material.metalness = 0.72;
  nucleus.material.roughness = 0.14;
  nucleus.material.emissive = '#3b1a8a';
  nucleus.material.emissiveIntensity = 0.32;
  nucleus.keyframes.position = [
    { t: 0, v: [0, 1.62, 0], ease: 'easeInOut' },
    { t: 1.5, v: [0, 1.84, 0], ease: 'easeInOut' },
    { t: 3, v: [0, 1.62, 0], ease: 'easeInOut' },
    { t: 4.5, v: [0, 1.78, 0], ease: 'easeInOut' },
    { t: 6, v: [0, 1.62, 0], ease: 'easeInOut' },
  ];
  nucleus.keyframes.rotation = [
    { t: 0, v: [0, 0, 0], ease: 'linear' },
    { t: 6, v: [0, Math.PI * 2, 0], ease: 'linear' },
  ];
  nucleus.keyframes.scale = [
    { t: 0, v: [1, 1, 1], ease: 'easeInOut' },
    { t: 1.5, v: [1.05, 1.05, 1.05], ease: 'easeInOut' },
    { t: 3, v: [1, 1, 1], ease: 'easeInOut' },
    { t: 4.5, v: [1.03, 1.03, 1.03], ease: 'easeInOut' },
    { t: 6, v: [1, 1, 1], ease: 'easeInOut' },
  ];
  project.objects.push(nucleus);

  const ring = createPrimitive('torus', project, {
    name: 'Anel principal',
    position: [0, 1.62, 0],
    color: '#22d3ee',
  });
  ring.transform.rotation = [Math.PI / 2.6, 0, 0.25];
  ring.transform.scale = [1.05, 1.05, 1.05];
  ring.material.metalness = 0.85;
  ring.material.roughness = 0.22;
  ring.material.emissive = '#0891b2';
  ring.material.emissiveIntensity = 0.55;
  ring.keyframes.rotation = [
    { t: 0, v: [Math.PI / 2.6, 0, 0.25], ease: 'linear' },
    { t: 6, v: [Math.PI / 2.6, 0, 0.25 + Math.PI * 2], ease: 'linear' },
  ];
  project.objects.push(ring);

  const ring2 = createPrimitive('torus', project, {
    name: 'Anel fino',
    position: [0, 1.62, 0],
    color: '#a78bfa',
  });
  ring2.transform.rotation = [-Math.PI / 3.4, 0.5, -0.2];
  ring2.transform.scale = [1.42, 1.42, 1.42];
  ring2.material.metalness = 0.7;
  ring2.material.roughness = 0.3;
  ring2.material.emissive = '#6d28d9';
  ring2.material.emissiveIntensity = 0.35;
  ring2.keyframes.rotation = [
    { t: 0, v: [-Math.PI / 3.4, 0.5, -0.2], ease: 'linear' },
    { t: 6, v: [-Math.PI / 3.4, 0.5, -0.2 - Math.PI * 2], ease: 'linear' },
  ];
  project.objects.push(ring2);

  const satelliteColors = ['#22d3ee', '#fbbf24', '#fb7185'];
  const satelliteNames = ['Satélite ciano', 'Satélite âmbar', 'Satélite coral'];
  const heights = [0.72, 1.62, 2.48];
  const radius = 2.12;
  for (let i = 0; i < 3; i += 1) {
    const phase = (Math.PI * 2 * i) / 3;
    const cube = createPrimitive('box', project, {
      name: satelliteNames[i],
      position: [Math.cos(phase) * radius, heights[i], Math.sin(phase) * radius],
      color: satelliteColors[i],
    });
    cube.transform.rotation = [0.3, phase, 0.2];
    cube.transform.scale = [0.28, 0.28, 0.28];
    cube.material.metalness = 0.5;
    cube.material.roughness = 0.24;
    cube.material.emissive = satelliteColors[i];
    cube.material.emissiveIntensity = 0.22;
    cube.keyframes.position = orbitKeys(radius, [0, 0, 0], phase, 6, 8, 0).map((k) => ({
      ...k,
      v: [k.v[0], heights[i], k.v[2]],
    }));
    cube.keyframes.rotation = [
      { t: 0, v: [0.3, phase, 0.2], ease: 'linear' },
      { t: 6, v: [0.3 + Math.PI * 2, phase, 0.2], ease: 'linear' },
    ];
    project.objects.push(cube);
  }

  return project;
}

export function sampleTrack(keys, time) {
  if (!keys || keys.length === 0) return null;
  if (keys.length === 1) return [...keys[0].v];
  const first = keys[0];
  if (time <= first.t) return [...first.v];
  const last = keys[keys.length - 1];
  if (time >= last.t) return [...last.v];
  let a = keys[0];
  let b = keys[1];
  for (let i = 0; i < keys.length - 1; i += 1) {
    if (time >= keys[i].t && time <= keys[i + 1].t) {
      a = keys[i];
      b = keys[i + 1];
      break;
    }
  }
  const span = b.t - a.t;
  const raw = span <= 1e-6 ? 1 : (time - a.t) / span;
  const ease = EASINGS[a.ease] || EASINGS.easeInOut;
  const p = ease(clamp(raw, 0, 1));
  return [
    a.v[0] + (b.v[0] - a.v[0]) * p,
    a.v[1] + (b.v[1] - a.v[1]) * p,
    a.v[2] + (b.v[2] - a.v[2]) * p,
  ];
}

export function keyframeAt(keys, time, epsilon = 0.001) {
  return keys.find((k) => Math.abs(k.t - time) <= epsilon) || null;
}

export function upsertKeyframe(keys, time, value, ease = 'easeInOut') {
  const t = roundTime(time);
  let key = keyframeAt(keys, t);
  if (key) {
    key.v = [...value];
    key.ease = ease;
  } else {
    key = { t, v: [...value], ease };
    keys.push(key);
  }
  keys.sort((a, b) => a.t - b.t);
  return key;
}

export function sortKeys(keys) {
  keys.sort((a, b) => a.t - b.t);
  return keys;
}

export function removeKeyframe(keys, ref) {
  const i = keys.indexOf(ref);
  if (i >= 0) keys.splice(i, 1);
}

export function trackHasKeys(object, track) {
  return Array.isArray(object.keyframes?.[track]) && object.keyframes[track].length > 0;
}

export function objectIsAnimated(object) {
  return Object.keys(TRACK_META).some((track) => trackHasKeys(object, track));
}

export function applyPreset(object, presetId, duration) {
  const d = Math.max(1, Number(duration) || 6);
  const p = object.transform.position;
  const r = object.transform.rotation;
  const s = object.transform.scale;
  const pos = () => [...p];
  const rot = () => [...r];
  const sca = () => [...s];

  switch (presetId) {
    case 'spin':
      object.keyframes.rotation = [
        { t: 0, v: rot(), ease: 'linear' },
        { t: d, v: [r[0], r[1] + Math.PI * 2, r[2]], ease: 'linear' },
      ];
      break;
    case 'float': {
      const amp = Math.max(0.18, 0.26 * Math.abs(s[1]));
      object.keyframes.position = [
        { t: 0, v: pos(), ease: 'easeInOut' },
        { t: d * 0.25, v: [p[0], p[1] + amp, p[2]], ease: 'easeInOut' },
        { t: d * 0.5, v: [...p], ease: 'easeInOut' },
        { t: d * 0.75, v: [p[0], p[1] + amp * 0.75, p[2]], ease: 'easeInOut' },
        { t: d, v: [...p], ease: 'easeInOut' },
      ];
      break;
    }
    case 'bounce': {
      const amp = Math.max(0.5, 1.1 * Math.abs(s[1]));
      object.keyframes.position = [
        { t: 0, v: pos(), ease: 'easeOut' },
        { t: d * 0.18, v: [p[0], p[1] + amp, p[2]], ease: 'easeIn' },
        { t: d * 0.36, v: [...p], ease: 'easeOut' },
        { t: d * 0.52, v: [p[0], p[1] + amp * 0.45, p[2]], ease: 'easeIn' },
        { t: d * 0.66, v: [...p], ease: 'easeOut' },
        { t: d * 0.78, v: [p[0], p[1] + amp * 0.16, p[2]], ease: 'easeIn' },
        { t: d * 0.88, v: [...p], ease: 'easeOut' },
        { t: d, v: [p[0], p[1] + 0.02, p[2]], ease: 'easeInOut' },
      ];
      break;
    }
    case 'pulse': {
      const keys = [];
      const steps = 8;
      for (let i = 0; i <= steps; i += 1) {
        const wave = Math.sin((i / steps) * Math.PI * 2);
        const k = 1 + 0.14 * wave;
        keys.push({ t: roundTime((i / steps) * d), v: [s[0] * k, s[1] * k, s[2] * k], ease: 'easeInOut' });
      }
      object.keyframes.scale = keys;
      break;
    }
    case 'orbit': {
      const radius = Math.max(1.1, Math.hypot(p[0], p[2]));
      const phase = Math.atan2(p[2], p[0]);
      object.keyframes.position = orbitKeys(radius, [0, 0, 0], phase, d, 8, p[1]);
      break;
    }
    case 'entrance': {
      object.keyframes.scale = [
        { t: 0, v: [s[0] * 0.01, s[1] * 0.01, s[2] * 0.01], ease: 'backOut' },
        { t: d * 0.3, v: [s[0] * 1.08, s[1] * 1.08, s[2] * 1.08], ease: 'easeInOut' },
        { t: d * 0.42, v: [...s], ease: 'easeInOut' },
        { t: d, v: [...s], ease: 'linear' },
      ];
      object.keyframes.position = [
        { t: 0, v: [p[0], p[1] + Math.max(1.2, 2.2 * Math.abs(s[1])), p[2]], ease: 'backOut' },
        { t: d * 0.42, v: [...p], ease: 'linear' },
        { t: d, v: [...p], ease: 'linear' },
      ];
      break;
    }
    case 'swing': {
      const amp = 0.28;
      object.keyframes.rotation = [
        { t: 0, v: rot(), ease: 'easeInOut' },
        { t: d * 0.25, v: [r[0], r[1], r[2] + amp], ease: 'easeInOut' },
        { t: d * 0.5, v: [r[0], r[1], r[2] - amp], ease: 'easeInOut' },
        { t: d * 0.75, v: [r[0], r[1], r[2] + amp * 0.6], ease: 'easeInOut' },
        { t: d, v: rot(), ease: 'easeInOut' },
      ];
      break;
    }
    case 'shake': {
      const keys = [];
      const steps = 12;
      for (let i = 0; i <= steps; i += 1) {
        const decay = 1 - i / steps;
        const ox = Math.sin(i * 2.7) * 0.075 * decay;
        const oy = Math.cos(i * 3.4) * 0.05 * decay;
        keys.push({
          t: roundTime((i / steps) * d),
          v: [p[0] + ox, p[1] + oy, p[2] + Math.sin(i * 4.1) * 0.05 * decay],
          ease: 'linear',
        });
      }
      object.keyframes.position = keys;
      break;
    }
    default:
      break;
  }
  return object;
}

export function setTransformFromArray(object, prop, value) {
  object.transform[prop] = value.map((n) => Number(n) || 0);
}

export function cloneObjectTree(project, sourceId) {
  const source = project.objects.find((o) => o.id === sourceId);
  if (!source) return [];
  const group = [];
  const cloneOne = (obj, parentId) => {
    const copy = structuredClone(obj);
    copy.id = uid(obj.kind === 'mesh' ? 'mesh' : obj.kind === 'light' ? 'lgt' : obj.kind === 'camera' ? 'cam' : 'grp');
    copy.parentId = parentId;
    copy.name = uniqueName(project.objects, obj.name);
    project.objects.push(copy);
    group.push(copy);
    project.objects.filter((o) => o.parentId === obj.id).forEach((child) => cloneOne(child, copy.id));
    return copy;
  };
  cloneOne(source, source.parentId);
  return group;
}

export function descendantIds(project, id) {
  const out = [id];
  for (let i = 0; i < out.length; i += 1) {
    project.objects.filter((o) => o.parentId === out[i]).forEach((o) => out.push(o.id));
  }
  return out;
}

export function isDescendant(project, candidateId, ancestorId) {
  let current = project.objects.find((o) => o.id === candidateId);
  while (current && current.parentId) {
    if (current.parentId === ancestorId) return true;
    current = project.objects.find((o) => o.id === current.parentId);
  }
  return false;
}

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { TransformControls } from 'three/addons/controls/TransformControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { clone as cloneSkeleton } from 'three/addons/utils/SkeletonUtils.js';
import { clamp, sampleTrack, uid } from './model.js';

const _box = new THREE.Box3();
const _size = new THREE.Vector3();
const _center = new THREE.Vector3();
const _world = new THREE.Vector3();
const _dir = new THREE.Vector3();
const _target = new THREE.Vector3();
const _quat = new THREE.Quaternion();
const _mat = new THREE.Matrix4();

function geometryFor(type) {
  switch (type) {
    case 'sphere':
      return new THREE.SphereGeometry(0.75, 64, 48);
    case 'cylinder':
      return new THREE.CylinderGeometry(0.5, 0.5, 1, 64, 1, false);
    case 'cone':
      return new THREE.ConeGeometry(0.6, 1.4, 64);
    case 'torus':
      return new THREE.TorusGeometry(1, 0.032, 20, 128);
    case 'plane':
      return new THREE.PlaneGeometry(2, 2);
    case 'box':
    default:
      return new THREE.BoxGeometry(1, 1, 1);
  }
}

function base64ToArrayBuffer(base64) {
  const clean = base64.includes(',') ? base64.slice(base64.indexOf(',') + 1) : base64;
  const binary = atob(clean);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

function easeOutCubic(t) {
  return 1 - Math.pow(1 - t, 3);
}

export class Engine {
  constructor(container, callbacks = {}) {
    this.container = container;
    this.callbacks = callbacks;
    this.project = null;
    this.runtime = new Map();
    this.assetCache = new Map();
    this.selectedId = null;
    this.liveCamera = false;
    this.dragging = false;
    this.lastTransformEnd = 0;
    this.currentTime = 0;
    this.buildToken = 0;
    this.tween = null;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color('#060913');
    this.scene.fog = new THREE.FogExp2('#060913', 0.022);

    this.renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
      preserveDrawingBuffer: true,
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.08;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.domElement.className = 'scene-canvas';
    this.renderer.domElement.setAttribute('aria-label', 'Viewport 3D da cena');
    this.container.appendChild(this.renderer.domElement);

    this.camera = new THREE.PerspectiveCamera(42, 1, 0.1, 500);
    this.camera.position.set(7.2, 4.8, 9.8);
    this.shotCamera = new THREE.PerspectiveCamera(45, 1, 0.1, 500);
    this.shotCamera.position.set(6.6, 4.4, 9.2);
    this.shotCamera.lookAt(0, 1.2, 0);
    this.shotCamera.name = 'Câmera';

    this.helpers = new THREE.Group();
    this.helpers.name = 'Ajudantes do editor';
    this.content = new THREE.Group();
    this.content.name = 'Cena';
    this.scene.add(this.helpers, this.content);

    this.buildEnvironment();
    this.buildGround();
    this.buildSelection();

    this.orbit = new OrbitControls(this.camera, this.renderer.domElement);
    this.orbit.enableDamping = true;
    this.orbit.dampingFactor = 0.075;
    this.orbit.minDistance = 1.4;
    this.orbit.maxDistance = 90;
    this.orbit.maxPolarAngle = Math.PI / 2 - 0.012;
    this.orbit.target.set(0, 1.3, 0);
    this.orbit.addEventListener('start', () => {
      this.tween = null;
    });

    this.transform = new TransformControls(this.camera, this.renderer.domElement);
    this.transform.setSize(0.92);
    this.transform.setSpace('world');
    this.transform.addEventListener('dragging-changed', (event) => {
      this.dragging = event.value;
      this.orbit.enabled = !event.value && !this.liveCamera;
      if (event.value) this.transformActive = true;
      if (!event.value) {
        this.lastTransformEnd = performance.now();
        this.transformActive = false;
        this.callbacks.onTransformCommit?.();
      }
    });
    this.transform.addEventListener('objectChange', () => {
      this.callbacks.onTransform?.();
    });
    this.scene.add(this.transform.getHelper());

    this.loader = new GLTFLoader();

    this.raycaster = new THREE.Raycaster();
    this.pointer = new THREE.Vector2();
    this.pointerDown = null;
    this.bindPointer();

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(this.container);
    this.resize();
  }

  buildEnvironment() {
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    const environment = new RoomEnvironment();
    this.environmentMap = pmrem.fromScene(environment, 0.04).texture;
    environment.dispose?.();
    pmrem.dispose();
    this.scene.environment = this.environmentMap;
    this.scene.environmentIntensity = 0.55;

    const hemi = new THREE.HemisphereLight(0x8fb4ff, 0x05070d, 0.32);
    this.helpers.add(hemi);

    const count = 260;
    const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i += 1) {
      const r = 4 + Math.random() * 17;
      const a = Math.random() * Math.PI * 2;
      positions[i * 3] = Math.cos(a) * r;
      positions[i * 3 + 1] = 0.3 + Math.random() * 9;
      positions[i * 3 + 2] = Math.sin(a) * r;
    }
    const dustGeo = new THREE.BufferGeometry();
    dustGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const dustMat = new THREE.PointsMaterial({
      color: 0x7dd3fc,
      size: 0.032,
      transparent: true,
      opacity: 0.42,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    });
    this.dust = new THREE.Points(dustGeo, dustMat);
    this.dust.frustumCulled = false;
    this.helpers.add(this.dust);
  }

  buildGround() {
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x070b13,
      roughness: 0.9,
      metalness: 0.16,
      envMapIntensity: 0.7,
    });
    this.ground = new THREE.Mesh(new THREE.PlaneGeometry(160, 160), groundMat);
    this.ground.rotation.x = -Math.PI / 2;
    this.ground.position.y = -0.012;
    this.ground.receiveShadow = true;
    this.ground.name = 'Chão';
    this.helpers.add(this.ground);

    this.grid = new THREE.GridHelper(48, 96, 0x2c4266, 0x111c30);
    this.grid.position.y = 0.002;
    if (Array.isArray(this.grid.material)) {
      this.grid.material.forEach((m) => {
        m.transparent = true;
        m.opacity = 0.55;
        m.depthWrite = false;
      });
    } else {
      this.grid.material.transparent = true;
      this.grid.material.opacity = 0.55;
      this.grid.material.depthWrite = false;
    }
    this.helpers.add(this.grid);
  }

  buildSelection() {
    const geo = new THREE.EdgesGeometry(new THREE.BoxGeometry(1, 1, 1));
    const mat = new THREE.LineBasicMaterial({
      color: 0x67e8f9,
      transparent: true,
      opacity: 0.95,
      depthTest: false,
      depthWrite: false,
    });
    this.selection = new THREE.LineSegments(geo, mat);
    this.selection.renderOrder = 999;
    this.selection.visible = false;
    this.selection.frustumCulled = false;
    this.helpers.add(this.selection);
  }

  bindPointer() {
    const canvas = this.renderer.domElement;
    canvas.addEventListener('pointerdown', (event) => {
      if (event.button !== 0) return;
      this.pointerDown = { x: event.clientX, y: event.clientY, t: performance.now() };
    });
    canvas.addEventListener('pointerup', (event) => {
      if (event.button !== 0 || !this.pointerDown) return;
      const dist = Math.hypot(event.clientX - this.pointerDown.x, event.clientY - this.pointerDown.y);
      const elapsed = performance.now() - this.pointerDown.t;
      const skip = performance.now() - this.lastTransformEnd < 180;
      this.pointerDown = null;
      if (dist > 6 || elapsed > 800 || skip || this.transformActive) return;
      const id = this.pick(event.clientX, event.clientY);
      this.callbacks.onSelect?.(id);
    });
    canvas.addEventListener('dblclick', (event) => {
      const id = this.pick(event.clientX, event.clientY);
      if (id) this.focusObject(id);
    });
  }

  pick(clientX, clientY) {
    const rect = this.renderer.domElement.getBoundingClientRect();
    this.pointer.x = ((clientX - rect.left) / rect.width) * 2 - 1;
    this.pointer.y = -((clientY - rect.top) / rect.height) * 2 + 1;
    this.raycaster.setFromCamera(this.pointer, this.getCamera());
    const hits = this.raycaster.intersectObjects(this.content.children, true);
    for (const hit of hits) {
      let node = hit.object;
      while (node) {
        if (node.userData?.objectId) return node.userData.objectId;
        node = node.parent;
      }
    }
    return null;
  }

  async parseModel(buffer) {
    const gltf = await this.loader.parseAsync(buffer, '');
    const id = uid('asset');
    this.assetCache.set(id, Promise.resolve({ scene: gltf.scene, animations: gltf.animations }));
    return {
      assetId: id,
      animations: gltf.animations.map((clip, index) => ({
        name: clip.name || `Clipe ${index + 1}`,
        duration: clip.duration,
      })),
      objectName: gltf.scene?.name || '',
    };
  }

  async loadAsset(asset) {
    if (!asset) throw new Error('Modelo sem dados');
    if (this.assetCache.has(asset.id)) return this.assetCache.get(asset.id);
    const promise = (async () => {
      const buffer = base64ToArrayBuffer(asset.data);
      const gltf = await this.loader.parseAsync(buffer, '');
      return { scene: gltf.scene, animations: gltf.animations };
    })();
    this.assetCache.set(asset.id, promise);
    return promise;
  }

  disposeContent() {
    this.content.traverse((node) => {
      if (!node.isMesh) return;
      if (node.userData.sharedAsset) return;
      node.geometry?.dispose();
      if (Array.isArray(node.material)) node.material.forEach((m) => m.dispose());
      else node.material?.dispose();
    });
  }

  async build(project, { selectedId = null, time = 0 } = {}) {
    this.project = project;
    this.buildToken += 1;
    const token = this.buildToken;
    this.transform.detach();
    this.runtime.clear();
    this.disposeContent();
    this.content.clear();
    this.content.add(this.shotCamera);
    this.shotCamera.userData.objectId = '';

    const models = project.objects || [];
    const cameraModel = models.find((m) => m.kind === 'camera');
    if (cameraModel) {
      this.shotCamera.userData.objectId = cameraModel.id;
      this.shotCamera.name = cameraModel.name;
    }

    for (const model of models) {
      if (model.kind === 'camera') {
        this.runtime.set(model.id, {
          model,
          object3d: this.shotCamera,
          kind: 'camera',
          mixer: null,
          clips: [],
          activeAction: null,
        });
        continue;
      }
      if (model.kind === 'imported') {
        const root = new THREE.Group();
        root.name = model.name;
        root.userData.objectId = model.id;
        this.runtime.set(model.id, {
          model,
          object3d: root,
          kind: 'imported',
          mixer: null,
          clips: [],
          activeAction: null,
          animationRoot: null,
        });
        continue;
      }
      if (model.kind === 'light') {
        const light = this.createLight(model);
        light.userData.objectId = model.id;
        light.name = model.name;
        this.runtime.set(model.id, { model, object3d: light, kind: 'light' });
        continue;
      }
      if (model.kind === 'group') {
        const group = new THREE.Group();
        group.userData.objectId = model.id;
        group.name = model.name;
        this.runtime.set(model.id, { model, object3d: group, kind: 'group' });
        continue;
      }
      const geometry = geometryFor(model.geometry?.type || 'box');
      const material = this.createMaterial(model.material);
      const mesh = new THREE.Mesh(geometry, material);
      mesh.userData.objectId = model.id;
      mesh.name = model.name;
      mesh.castShadow = model.castShadow !== false;
      mesh.receiveShadow = model.receiveShadow !== false;
      this.runtime.set(model.id, { model, object3d: mesh, kind: 'mesh' });
    }

    for (const model of models) {
      if (model.kind === 'camera') continue;
      const entry = this.runtime.get(model.id);
      if (!entry) continue;
      const parent = model.parentId ? this.runtime.get(model.parentId)?.object3d : null;
      (parent || this.content).add(entry.object3d);
      this.applyObjectState(model);
    }

    const clipPromises = [];
    for (const model of models) {
      if (model.kind !== 'imported' || !model.asset) continue;
      const entry = this.runtime.get(model.id);
      clipPromises.push(this.loadImported(entry, model, token));
    }
    await Promise.all(clipPromises);
    if (token !== this.buildToken) return;

    this.applyEditorCamera(project.camera, true);
    this.applySettings(project.settings);
    this.currentTime = time;
    this.applyTime(time);
    this.setSelection(selectedId);
    this.resize();
  }

  createMaterial(source = {}) {
    const material = new THREE.MeshStandardMaterial({
      color: new THREE.Color(source.color || '#8b5cf6'),
      metalness: source.metalness ?? 0.35,
      roughness: source.roughness ?? 0.3,
      emissive: new THREE.Color(source.emissive || '#000000'),
      emissiveIntensity: source.emissiveIntensity ?? 0,
      transparent: (source.opacity ?? 1) < 1,
      opacity: source.opacity ?? 1,
      wireframe: !!source.wireframe,
      flatShading: !!source.flatShading,
      envMapIntensity: 0.95,
    });
    material.name = 'Material';
    return material;
  }

  createLight(model) {
    const data = model.light || {};
    let light;
    if (data.type === 'directional') {
      light = new THREE.DirectionalLight(new THREE.Color(data.color || '#ffffff'), data.intensity ?? 3);
      light.castShadow = model.castShadow !== false;
      light.shadow.mapSize.set(2048, 2048);
      light.shadow.camera.left = -12;
      light.shadow.camera.right = 12;
      light.shadow.camera.top = 12;
      light.shadow.camera.bottom = -12;
      light.shadow.camera.near = 0.5;
      light.shadow.camera.far = 45;
      light.shadow.bias = -0.0004;
      light.shadow.normalBias = 0.02;
      light.shadow.camera.updateProjectionMatrix();
    } else if (data.type === 'spot') {
      light = new THREE.SpotLight(
        new THREE.Color(data.color || '#ffffff'),
        data.intensity ?? 80,
        data.distance ?? 30,
        data.angle ?? Math.PI / 6,
        data.penumbra ?? 0.5,
        2,
      );
      light.castShadow = model.castShadow !== false;
      light.shadow.mapSize.set(1024, 1024);
      light.shadow.bias = -0.0003;
      light.shadow.normalBias = 0.02;
    } else {
      light = new THREE.PointLight(
        new THREE.Color(data.color || '#ffffff'),
        data.intensity ?? 40,
        data.distance ?? 0,
        2,
      );
    }
    light.position.fromArray(model.transform.position);
    this.content.add(light.target);
    return light;
  }

  async loadImported(entry, model, token) {
    if (!entry) return;
    try {
      const template = await this.loadAsset(model.asset);
      if (token !== this.buildToken) return;
      const inner = cloneSkeleton(template.scene);
      inner.updateMatrixWorld(true);
      _box.setFromObject(inner);
      if (!_box.isEmpty()) {
        _box.getSize(_size);
        _box.getCenter(_center);
        const maxDim = Math.max(_size.x, _size.y, _size.z) || 1;
        const scale = 2.2 / maxDim;
        inner.scale.setScalar(scale);
        inner.position.set(-_center.x * scale, -_box.min.y * scale, -_center.z * scale);
      }
      inner.traverse((node) => {
        if (node.isMesh) {
          node.castShadow = true;
          node.receiveShadow = true;
          node.userData.sharedAsset = true;
          if (node.material) {
            if (Array.isArray(node.material)) {
              node.material.forEach((m) => {
                m.envMapIntensity = 0.9;
              });
            } else {
              node.material.envMapIntensity = 0.9;
            }
          }
        }
      });
      const root = entry.object3d;
      root.add(inner);
      entry.inner = inner;
      entry.animationRoot = inner;
      entry.clips = template.animations || [];
      if (entry.clips.length > 0) {
        entry.mixer = new THREE.AnimationMixer(inner);
        this.configureClip(entry, model);
      }
      this.applyObjectState(model);
      this.applyTime(this.currentTime);
    } catch (error) {
      console.error('Falha ao carregar modelo importado', error);
      entry.failed = true;
      this.callbacks.onAssetError?.(model, error);
    }
  }

  configureClip(entry, model) {
    if (!entry?.mixer) return;
    entry.mixer.stopAllAction();
    entry.activeAction = null;
    if (!model.clip || model.clip.enabled === false) return;
    if (!entry.clips.length) return;
    const index = clamp(model.clip.index || 0, 0, entry.clips.length - 1);
    const clip = entry.clips[index];
    if (!clip) return;
    const action = entry.mixer.clipAction(clip);
    action.reset();
    action.setLoop(THREE.LoopRepeat, Infinity);
    action.enabled = true;
    action.play();
    entry.activeAction = action;
    entry.mixer.setTime(0);
  }

  applyObjectState(model) {
    const entry = this.runtime.get(model.id);
    if (!entry) return;
    const object = entry.object3d;
    object.name = model.name;
    object.visible = model.visible !== false;
    if (model.kind === 'camera') {
      object.position.fromArray(model.transform.position);
      object.fov = model.fov || 45;
      object.updateProjectionMatrix();
      return;
    }
    object.position.fromArray(model.transform.position);
    object.rotation.set(...model.transform.rotation.map(Number));
    object.scale.fromArray(model.transform.scale);
    if (model.kind === 'mesh' && object.isMesh) {
      object.castShadow = model.castShadow !== false;
      object.receiveShadow = model.receiveShadow !== false;
      const m = model.material || {};
      object.material.color.set(m.color || '#8b5cf6');
      object.material.metalness = m.metalness ?? 0.35;
      object.material.roughness = m.roughness ?? 0.3;
      object.material.emissive.set(m.emissive || '#000000');
      object.material.emissiveIntensity = m.emissiveIntensity ?? 0;
      object.material.opacity = m.opacity ?? 1;
      object.material.transparent = (m.opacity ?? 1) < 1;
      object.material.wireframe = !!m.wireframe;
      object.material.flatShading = !!m.flatShading;
      object.material.needsUpdate = true;
    }
    if (model.kind === 'light' && object.isLight) {
      const l = model.light || {};
      object.color.set(l.color || '#ffffff');
      object.intensity = l.intensity ?? object.intensity;
      if (object.distance !== undefined) object.distance = l.distance ?? object.distance;
      if (object.angle !== undefined) object.angle = l.angle ?? object.angle;
      if (object.penumbra !== undefined) object.penumbra = l.penumbra ?? object.penumbra;
      object.castShadow = model.castShadow !== false && (l.type === 'directional' || l.type === 'spot');
    }
    if (model.kind === 'imported') {
      object.traverse((node) => {
        if (node.isMesh) {
          node.castShadow = model.castShadow !== false;
          node.receiveShadow = model.receiveShadow !== false;
        }
      });
    }
  }

  applyEditorCamera(config, instant = false) {
    if (!config) return;
    if (instant) {
      this.camera.position.fromArray(config.position || [7, 4.5, 9]);
      this.orbit.target.fromArray(config.target || [0, 1, 0]);
      this.orbit.update();
    } else {
      this.tweenCamera(new THREE.Vector3().fromArray(config.position), new THREE.Vector3().fromArray(config.target));
    }
  }

  applySettings(settings = {}) {
    const color = new THREE.Color(settings.background || '#060913');
    this.scene.background = color;
    this.scene.fog = settings.fog === false ? null : new THREE.FogExp2(color, 0.021);
    this.scene.environmentIntensity = settings.environment ?? 0.55;
    this.renderer.shadowMap.enabled = settings.shadows !== false;
    this.renderer.shadowMap.needsUpdate = true;
    this.grid.visible = settings.grid !== false && !this.liveCamera;
    this.ground.visible = true;
  }

  setSelection(id) {
    this.selectedId = id;
    const entry = id ? this.runtime.get(id) : null;
    if (!entry || this.liveCamera) {
      this.transform.detach();
      this.selection.visible = false;
      return;
    }
    if (entry.kind === 'camera') {
      this.transform.attach(this.shotCamera);
    } else {
      this.transform.attach(entry.object3d);
    }
    this.transform.getHelper().visible = true;
    this.selection.visible = true;
    this.updateSelection();
  }

  updateSelection() {
    const entry = this.selectedId ? this.runtime.get(this.selectedId) : null;
    if (!entry || this.liveCamera) {
      this.selection.visible = false;
      return;
    }
    const object = entry.object3d;
    object.updateWorldMatrix(true, true);
    if (entry.kind === 'light' || entry.kind === 'camera') {
      object.getWorldPosition(_center);
      _size.set(0.45, 0.45, 0.45);
    } else {
      _box.setFromObject(object);
      if (_box.isEmpty()) {
        object.getWorldPosition(_center);
        _size.set(0.4, 0.4, 0.4);
      } else {
        _box.getSize(_size);
        _box.getCenter(_center);
        _size.multiplyScalar(1.08);
        _size.x = Math.max(_size.x, 0.18);
        _size.y = Math.max(_size.y, 0.18);
        _size.z = Math.max(_size.z, 0.18);
      }
    }
    this.selection.position.copy(_center);
    this.selection.scale.copy(_size);
    this.selection.visible = true;
  }

  applyTime(time) {
    this.currentTime = time;
    if (!this.project) return;
    for (const model of this.project.objects) {
      const entry = this.runtime.get(model.id);
      if (!entry || model.kind === 'camera') continue;
      const p = sampleTrack(model.keyframes?.position, time);
      if (p) entry.object3d.position.fromArray(p);
      const r = sampleTrack(model.keyframes?.rotation, time);
      if (r) entry.object3d.rotation.set(r[0], r[1], r[2]);
      const s = sampleTrack(model.keyframes?.scale, time);
      if (s) entry.object3d.scale.fromArray(s);
      if (entry.activeAction && model.clip) {
        const clip = entry.activeAction.getClip();
        const speed = model.clip.speed ?? 1;
        let local = time * speed;
        if (model.clip.loop === false) local = Math.min(local, clip.duration);
        else local = ((local % clip.duration) + clip.duration) % clip.duration;
        entry.mixer.setTime(local);
      }
    }
    this.applyCameraTime(time);
    this.updateSelection();
  }

  applyCameraTime(time) {
    if (!this.project) return;
    const model = this.project.objects.find((o) => o.kind === 'camera');
    if (!model) return;
    const entry = this.runtime.get(model.id);
    if (!entry) return;
    const pos = sampleTrack(model.keyframes?.position, time);
    if (pos) this.shotCamera.position.fromArray(pos);
    else this.shotCamera.position.fromArray(model.transform.position);
    const target = sampleTrack(model.keyframes?.target, time) || model.target || [0, 1.2, 0];
    this.shotCamera.up.set(0, 1, 0);
    this.shotCamera.lookAt(target[0], target[1], target[2]);
    const fov = model.fov || 45;
    if (this.shotCamera.fov !== fov) {
      this.shotCamera.fov = fov;
    }
    this.shotCamera.updateProjectionMatrix();
  }

  readTransform(id) {
    const entry = this.runtime.get(id);
    if (!entry) return null;
    const object = entry.object3d;
    return {
      position: [object.position.x, object.position.y, object.position.z],
      rotation: [object.rotation.x, object.rotation.y, object.rotation.z],
      scale: [object.scale.x, object.scale.y, object.scale.z],
    };
  }

  getBounds(id) {
    const entry = this.runtime.get(id);
    if (!entry) return null;
    const object = entry.object3d;
    object.updateWorldMatrix(true, true);
    if (entry.kind === 'camera') {
      object.getWorldPosition(_center);
      return { center: _center.clone(), size: new THREE.Vector3(0.4, 0.4, 0.4), empty: true };
    }
    _box.setFromObject(object);
    if (_box.isEmpty()) {
      object.getWorldPosition(_center);
      return { center: _center.clone(), size: new THREE.Vector3(0.4, 0.4, 0.4), empty: true };
    }
    _box.getSize(_size);
    _box.getCenter(_center);
    return { center: _center.clone(), size: _size.clone(), empty: false };
  }

  focusObject(id) {
    const bounds = this.getBounds(id);
    if (!bounds) return;
    const radius = Math.max(bounds.size.length() * 0.55, 0.9);
    const fov = (this.camera.fov * Math.PI) / 180;
    const distance = clamp((radius / Math.sin(fov / 2)) * 1.15, 2.2, 40);
    _dir.copy(this.camera.position).sub(this.orbit.target);
    if (_dir.lengthSq() < 0.0001) _dir.set(1, 0.7, 1);
    _dir.normalize();
    const to = bounds.center.clone().addScaledVector(_dir, distance);
    this.tweenCamera(to, bounds.center, 0.5);
  }

  setView(name) {
    const target = this.orbit.target.clone();
    const distance = Math.max(this.camera.position.distanceTo(target), 5);
    let pos;
    if (name === 'front') pos = target.clone().add(new THREE.Vector3(0, 0, distance));
    else if (name === 'side') pos = target.clone().add(new THREE.Vector3(distance, 0, 0.001));
    else if (name === 'top') pos = target.clone().add(new THREE.Vector3(0.001, distance, 0.001));
    else pos = target.clone().add(new THREE.Vector3(0.62, 0.45, 0.72).normalize().multiplyScalar(distance));
    this.tweenCamera(pos, target, 0.45);
  }

  tweenCamera(position, target, duration = 0.45) {
    this.tween = {
      fromPos: this.camera.position.clone(),
      fromTarget: this.orbit.target.clone(),
      toPos: position.clone(),
      toTarget: target.clone(),
      elapsed: 0,
      duration,
    };
  }

  setLiveCamera(enabled) {
    this.liveCamera = !!enabled;
    this.orbit.enabled = !enabled;
    this.transform.enabled = !enabled;
    this.transform.getHelper().visible = !enabled;
    if (enabled) {
      this.transform.detach();
      this.selection.visible = false;
    } else {
      this.setSelection(this.selectedId);
    }
    this.applySettings(this.project?.settings);
    this.updateSelection();
  }

  setClipSettings(id, index, enabled, speed) {
    const model = this.project?.objects.find((o) => o.id === id);
    const entry = this.runtime.get(id);
    if (!model || !entry) return;
    model.clip = { ...(model.clip || {}), index, enabled, speed };
    this.configureClip(entry, model);
    this.applyTime(this.currentTime);
  }

  update(dt) {
    if (!this.liveCamera) this.orbit.update();
    if (this.tween) {
      this.tween.elapsed += dt;
      const t = clamp(this.tween.elapsed / this.tween.duration, 0, 1);
      const e = easeOutCubic(t);
      this.camera.position.lerpVectors(this.tween.fromPos, this.tween.toPos, e);
      this.orbit.target.lerpVectors(this.tween.fromTarget, this.tween.toTarget, e);
      this.camera.lookAt(this.orbit.target);
      if (t >= 1) this.tween = null;
    }
    if (this.dust) this.dust.rotation.y += dt * 0.008;
    this.updateSelection();
  }

  render() {
    const camera = this.liveCamera ? this.shotCamera : this.camera;
    this.renderer.render(this.scene, camera);
  }

  getCamera() {
    return this.liveCamera ? this.shotCamera : this.camera;
  }

  resize() {
    const width = Math.max(1, this.container.clientWidth);
    const height = Math.max(1, this.container.clientHeight);
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.shotCamera.aspect = width / height;
    this.shotCamera.updateProjectionMatrix();
  }

  async exportGLB() {
    const { GLTFExporter } = await import('three/addons/exporters/GLTFExporter.js');
    const exporter = new GLTFExporter();
    const duration = this.project?.settings?.duration || 6;
    const fps = this.project?.settings?.fps || 30;
    const steps = Math.max(2, Math.round(duration * fps));
    const times = new Float32Array(steps + 1);
    for (let i = 0; i <= steps; i += 1) times[i] = (i / steps) * duration;

    const animations = [];
    const tmpEuler = new THREE.Euler();
    const tmpQuat = new THREE.Quaternion();
    const tmpPos = new THREE.Vector3();
    const tmpTarget = new THREE.Vector3();
    const lookMatrix = new THREE.Matrix4();

    for (const model of this.project.objects) {
      if (model.visible === false) continue;
      const entry = this.runtime.get(model.id);
      if (!entry) continue;
      const object = entry.object3d;
      const tracks = [];
      const hasPos = model.keyframes?.position?.length;
      const hasRot = model.keyframes?.rotation?.length;
      const hasScale = model.keyframes?.scale?.length;
      const hasTarget = model.keyframes?.target?.length;

      if (hasPos) {
        const values = new Float32Array((steps + 1) * 3);
        for (let i = 0; i <= steps; i += 1) {
          const p = sampleTrack(model.keyframes.position, times[i]);
          values.set(p, i * 3);
        }
        tracks.push(new THREE.VectorKeyframeTrack(`${object.uuid}.position`, times, values));
      }
      if (hasRot) {
        const values = new Float32Array((steps + 1) * 4);
        for (let i = 0; i <= steps; i += 1) {
          const r = sampleTrack(model.keyframes.rotation, times[i]);
          tmpEuler.set(r[0], r[1], r[2]);
          tmpQuat.setFromEuler(tmpEuler);
          values.set([tmpQuat.x, tmpQuat.y, tmpQuat.z, tmpQuat.w], i * 4);
        }
        tracks.push(new THREE.QuaternionKeyframeTrack(`${object.uuid}.quaternion`, times, values));
      }
      if (hasScale) {
        const values = new Float32Array((steps + 1) * 3);
        for (let i = 0; i <= steps; i += 1) {
          const s = sampleTrack(model.keyframes.scale, times[i]);
          values.set(s, i * 3);
        }
        tracks.push(new THREE.VectorKeyframeTrack(`${object.uuid}.scale`, times, values));
      }
      if (model.kind === 'camera' && (hasPos || hasTarget)) {
        const values = new Float32Array((steps + 1) * 4);
        for (let i = 0; i <= steps; i += 1) {
          const p = sampleTrack(model.keyframes.position, times[i]) || model.transform.position;
          const target = sampleTrack(model.keyframes.target, times[i]) || model.target || [0, 1.2, 0];
          tmpPos.fromArray(p);
          tmpTarget.fromArray(target);
          lookMatrix.lookAt(tmpPos, tmpTarget, new THREE.Vector3(0, 1, 0));
          tmpQuat.setFromRotationMatrix(lookMatrix);
          values.set([tmpQuat.x, tmpQuat.y, tmpQuat.z, tmpQuat.w], i * 4);
        }
        tracks.push(new THREE.QuaternionKeyframeTrack(`${object.uuid}.quaternion`, times, values));
      }
      if (tracks.length) {
        animations.push(new THREE.AnimationClip(model.name || 'Animação', duration, tracks));
      }
      if (entry.clips?.length) {
        entry.clips.forEach((clip) => animations.push(clip));
      }
    }

    this.transform.detach();
    const prevHelpers = this.helpers.visible;
    const prevSelection = this.selection.visible;
    this.helpers.visible = false;
    this.selection.visible = false;
    this.applyTime(0);
    try {
      const result = await exporter.parseAsync(this.scene, {
        binary: true,
        animations,
        onlyVisible: true,
      });
      return result;
    } finally {
      this.helpers.visible = prevHelpers;
      this.selection.visible = prevSelection;
      this.applyTime(this.currentTime);
      this.setSelection(this.selectedId);
    }
  }
}

export { base64ToArrayBuffer };

:root {
  color-scheme: dark;
  --bg: #05070d;
  --bg-2: #070b14;
  --panel: rgba(9, 14, 25, 0.82);
  --panel-solid: #0a101b;
  --panel-2: #0e1524;
  --panel-3: #121a2b;
  --line: rgba(148, 163, 184, 0.13);
  --line-strong: rgba(148, 163, 184, 0.22);
  --text: #e8eef9;
  --muted: #8390a8;
  --muted-2: #5f6c84;
  --accent: #67e8f9;
  --accent-soft: rgba(103, 232, 249, 0.13);
  --violet: #a78bfa;
  --violet-soft: rgba(167, 139, 250, 0.14);
  --amber: #fbbf24;
  --rose: #fb7185;
  --green: #34d399;
  --radius: 12px;
  --shadow: 0 18px 60px rgba(0, 0, 0, 0.5);
  --font: "Inter", "SF Pro Text", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: "SFMono-Regular", "JetBrains Mono", "Fira Code", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 13px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

::selection {
  background: rgba(103, 232, 249, 0.28);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.icon {
  display: block;
  flex: none;
  pointer-events: none;
}

kbd {
  display: inline-block;
  min-width: 17px;
  padding: 1px 4px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.04);
  color: #c7d2e5;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.4;
  text-align: center;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100dvh;
  min-height: 0;
  background:
    radial-gradient(1100px 650px at 52% -18%, rgba(73, 52, 156, 0.16), transparent 62%),
    radial-gradient(800px 500px at 100% 0%, rgba(14, 116, 144, 0.1), transparent 55%),
    linear-gradient(180deg, #070a12 0%, #05070d 70%);
}

/* ---------------------------------------------------------------- top bar */

.topbar {
  position: relative;
  z-index: 60;
  display: flex;
  flex: 0 0 58px;
  align-items: center;
  gap: 14px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
  background: rgba(6, 9, 16, 0.86);
  backdrop-filter: blur(18px) saturate(1.2);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: none;
  user-select: none;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(103, 232, 249, 0.24);
  border-radius: 10px;
  background:
    radial-gradient(circle at 30% 20%, rgba(103, 232, 249, 0.18), transparent 60%),
    linear-gradient(150deg, rgba(103, 232, 249, 0.1), rgba(167, 139, 250, 0.12));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 0 22px rgba(103, 232, 249, 0.08);
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.brand-name {
  font-size: 14px;
  font-weight: 750;
  letter-spacing: 0.14em;
  line-height: 1.1;
}

.brand-name span {
  margin-left: 1px;
  background: linear-gradient(100deg, var(--accent), var(--violet));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.brand-tag {
  color: var(--muted-2);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.project-block {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.project-name {
  width: min(320px, 30vw);
  padding: 3px 6px;
  border: 1px solid transparent;
  border-radius: 7px;
  outline: none;
  background: transparent;
  font-size: 14px;
  font-weight: 650;
  letter-spacing: -0.01em;
  transition: border-color 0.16s, background 0.16s;
}

.project-name:hover {
  border-color: var(--line);
}

.project-name:focus {
  border-color: rgba(103, 232, 249, 0.4);
  background: rgba(103, 232, 249, 0.05);
}

.save-state {
  display: flex;
  align-items: center;
  gap: 5px;
  padding-left: 7px;
  color: var(--muted-2);
  font-size: 10px;
}

.save-state i {
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: var(--green);
  box-shadow: 0 0 7px rgba(52, 211, 153, 0.8);
}

.save-state.is-dirty i {
  background: var(--amber);
  box-shadow: 0 0 7px rgba(251, 191, 36, 0.75);
}

.save-state.is-error i {
  background: var(--rose);
  box-shadow: 0 0 7px rgba(251, 113, 133, 0.75);
}

.top-actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}

.btn {
  display: inline-flex;
  height: 34px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.012)), var(--panel-2);
  color: #cbd5e6;
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.1s;
}

.btn:hover:not(:disabled) {
  border-color: var(--line-strong);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02)), var(--panel-3);
  color: #fff;
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn.primary {
  border-color: transparent;
  background: linear-gradient(120deg, #67e8f9 0%, #93c5fd 45%, #b79bfc 100%);
  color: #04121b;
  font-weight: 750;
  box-shadow: 0 4px 18px rgba(103, 232, 249, 0.17), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}

.btn.primary:hover:not(:disabled) {
  background: linear-gradient(120deg, #8df1ff 0%, #aed4ff 45%, #c9b3ff 100%);
  color: #031018;
}

.btn.icon-btn {
  width: 34px;
  padding: 0;
}

.btn.small {
  height: 28px;
  padding: 0 9px;
  font-size: 10.5px;
}

.btn.icon-btn.small {
  width: 28px;
  padding: 0;
}

.btn.tiny {
  height: 24px;
  padding: 0 8px;
  font-size: 10px;
}

.btn-group {
  display: flex;
  gap: 3px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(8, 13, 23, 0.6);
}

.btn-group .btn {
  border: 0;
  background: transparent;
  height: 28px;
}

.btn-group .btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.06);
}

.btn:focus-visible,
.tool-btn:focus-visible,
.transport-btn:focus-visible,
.play-btn:focus-visible,
.chip-toggle:focus-visible,
.menu-item:focus-visible,
.tree-row:focus-visible,
.preset-btn:focus-visible,
.add-chip:focus-visible {
  outline: 2px solid rgba(103, 232, 249, 0.85);
  outline-offset: 1px;
}

.menu-anchor {
  position: relative;
}

#exportCaret {
  display: grid;
  place-items: center;
  margin-left: -1px;
  opacity: 0.75;
}

#exportCaret svg {
  width: 13px;
  height: 13px;
}

.menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 80;
  width: 268px;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: #0a101b;
  box-shadow: var(--shadow);
  animation: menu-in 0.14s ease-out;
}

@keyframes menu-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.985);
  }
}

.menu[hidden] {
  display: none;
}

.menu-item {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 10px;
  padding: 9px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  text-align: left;
}

.menu-item:hover {
  background: rgba(255, 255, 255, 0.05);
}

.menu-ico {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  flex: none;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(103, 232, 249, 0.06);
  color: var(--accent);
}

.menu-item strong {
  display: block;
  font-size: 11.5px;
  font-weight: 650;
}

.menu-item small {
  display: block;
  margin-top: 2px;
  color: var(--muted-2);
  font-size: 9.5px;
}

/* ---------------------------------------------------------------- layout */

.workspace {
  display: grid;
  flex: 1 1 auto;
  grid-template-columns: 254px minmax(0, 1fr) 300px;
  gap: 8px;
  min-height: 0;
  padding: 8px 8px 0;
}

.panel {
  display: flex;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  backdrop-filter: blur(18px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.panel-head {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 13px 10px;
  border-bottom: 1px solid var(--line);
}

.panel-head h2 {
  margin: 0;
  color: #b9c6db;
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.panel-head p {
  margin: 3px 0 0;
  color: var(--muted-2);
  font-size: 10px;
}

.panel-scroll {
  min-height: 0;
  flex: 1;
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #263149 transparent;
}

.panel-scroll::-webkit-scrollbar,
.timeline-scroll::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

.panel-scroll::-webkit-scrollbar-thumb,
.timeline-scroll::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 99px;
  background: #29354a;
  background-clip: padding-box;
}

.panel-scroll::-webkit-scrollbar-thumb:hover,
.timeline-scroll::-webkit-scrollbar-thumb:hover {
  background: #3a4964;
  background-clip: padding-box;
}

.panel-scroll::-webkit-scrollbar-corner,
.timeline-scroll::-webkit-scrollbar-corner {
  background: transparent;
}

/* ---------------------------------------------------------------- scene panel */

.search-wrap {
  position: relative;
  margin: 9px 9px 4px;
}

.search-wrap .search-ico {
  position: absolute;
  top: 50%;
  left: 9px;
  color: var(--muted-2);
  transform: translateY(-50%);
}

.search-wrap .icon {
  width: 13px;
  height: 13px;
}

.search-wrap input {
  width: 100%;
  height: 30px;
  padding: 0 9px 0 29px;
  border: 1px solid var(--line);
  border-radius: 7px;
  outline: none;
  background: rgba(5, 9, 16, 0.55);
  color: var(--text);
  font-size: 11px;
}

.search-wrap input::placeholder {
  color: var(--muted-2);
}

.search-wrap input:focus {
  border-color: rgba(103, 232, 249, 0.4);
}

.scene-tree {
  padding: 4px 7px 8px;
}

.tree-row {
  position: relative;
  display: flex;
  height: 30px;
  align-items: center;
  gap: 6px;
  margin-bottom: 1px;
  padding-right: 5px;
  border-radius: 6px;
  color: #b8c4d8;
  font-size: 11.5px;
  outline: none;
  cursor: default;
  user-select: none;
}

.tree-row:hover {
  background: rgba(255, 255, 255, 0.045);
}

.tree-row.selected {
  background: linear-gradient(90deg, rgba(103, 232, 249, 0.14), rgba(167, 139, 250, 0.07));
  box-shadow: inset 2px 0 0 var(--accent);
  color: #fff;
}

.tree-caret {
  display: grid;
  place-items: center;
  width: 14px;
  height: 22px;
  flex: none;
  border: 0;
  background: transparent;
  color: var(--muted-2);
}

.tree-caret svg {
  width: 11px;
  height: 11px;
}

.tree-type {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  flex: none;
  border-radius: 5px;
  background: color-mix(in srgb, var(--node-color, #67e8f9) 13%, transparent);
  color: var(--node-color, #67e8f9);
}

.tree-type .icon {
  width: 13px;
  height: 13px;
}

.tree-row.is-light .tree-type {
  background: rgba(251, 191, 36, 0.12);
  color: var(--amber);
}

.tree-row.is-camera .tree-type {
  background: rgba(251, 113, 133, 0.12);
  color: var(--rose);
}

.tree-row.is-group .tree-type {
  background: rgba(167, 139, 250, 0.13);
  color: var(--violet);
}

.tree-row.is-imported .tree-type {
  background: rgba(52, 211, 153, 0.12);
  color: var(--green);
}

.tree-name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tree-name-input {
  min-width: 0;
  flex: 1;
  height: 22px;
  padding: 0 4px;
  border: 1px solid rgba(103, 232, 249, 0.5);
  border-radius: 4px;
  outline: none;
  background: #050a12;
  font-size: 11.5px;
}

.anim-dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 6px rgba(103, 232, 249, 0.7);
}

.tree-eye {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: none;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--muted-2);
  opacity: 0;
}

.tree-row:hover .tree-eye,
.tree-row.selected .tree-eye,
.tree-eye.is-off {
  opacity: 1;
}

.tree-eye:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.tree-eye .icon {
  width: 13px;
  height: 13px;
}

.tree-eye.is-off {
  color: var(--muted-2);
}

.tree-empty {
  padding: 18px 10px;
  color: var(--muted-2);
  font-size: 10.5px;
  line-height: 1.6;
  text-align: center;
}

.add-area {
  position: relative;
  margin: 2px 9px 0;
}

.add-main {
  display: flex;
  width: 100%;
  height: 36px;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid rgba(103, 232, 249, 0.21);
  border-radius: 8px;
  background:
    linear-gradient(100deg, rgba(103, 232, 249, 0.09), rgba(167, 139, 250, 0.08)),
    var(--panel-2);
  color: #d9f7ff;
  font-size: 11.5px;
  font-weight: 600;
}

.add-main:hover {
  border-color: rgba(103, 232, 249, 0.45);
  background:
    linear-gradient(100deg, rgba(103, 232, 249, 0.15), rgba(167, 139, 250, 0.12)),
    var(--panel-2);
}

.add-main .icon {
  width: 15px;
  height: 15px;
}

.add-caret {
  display: grid;
  place-items: center;
  margin-left: auto;
  color: var(--muted);
}

.add-caret .icon {
  width: 13px;
  height: 13px;
  transition: transform 0.18s;
}

.add-main.open .add-caret .icon {
  transform: rotate(180deg);
}

.add-menu {
  margin-top: 7px;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(7, 11, 19, 0.94);
  animation: menu-in 0.15s ease-out;
}

.add-menu[hidden] {
  display: none;
}

.add-section-label {
  margin: 2px 2px 6px;
  color: var(--muted-2);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.add-section-label:not(:first-child) {
  margin-top: 10px;
}

.add-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
}

.add-grid-wide {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.add-chip {
  display: flex;
  min-width: 0;
  height: 44px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.018);
  color: #a9b7cd;
  font-size: 9px;
  font-weight: 550;
  line-height: 1.15;
}

.add-grid-wide .add-chip {
  height: 32px;
  flex-direction: row;
  justify-content: flex-start;
  gap: 6px;
  padding: 0 7px;
  font-size: 9.5px;
}

.add-chip:hover {
  border-color: rgba(103, 232, 249, 0.36);
  background: rgba(103, 232, 249, 0.07);
  color: #fff;
}

.add-chip .icon {
  width: 15px;
  height: 15px;
  color: var(--accent);
}

.import-btn {
  display: flex;
  width: calc(100% - 18px);
  min-height: 46px;
  align-items: center;
  gap: 9px;
  margin: 8px 9px 0;
  padding: 7px 9px;
  border: 1px dashed rgba(148, 163, 184, 0.23);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.014);
  text-align: left;
}

.import-btn:hover {
  border-color: rgba(103, 232, 249, 0.45);
  background: rgba(103, 232, 249, 0.05);
}

.import-ico {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: none;
  border-radius: 7px;
  background: rgba(52, 211, 153, 0.1);
  color: var(--green);
}

.import-ico .icon {
  width: 15px;
  height: 15px;
}

.import-btn strong {
  display: block;
  color: #b8c6da;
  font-size: 10px;
  font-weight: 600;
}

.import-btn small {
  display: block;
  margin-top: 1px;
  color: var(--muted-2);
  font-size: 8.5px;
}

.panel-section {
  margin-top: 10px;
  padding: 11px 9px 2px;
  border-top: 1px solid var(--line);
}

.section-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 7px;
  padding: 0 2px;
  color: #aab7cb;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.section-hint {
  color: var(--muted-2);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
}

.preset-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 5px;
}

.preset-btn {
  display: flex;
  height: 32px;
  align-items: center;
  gap: 6px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.018);
  color: #a9b7cd;
  font-size: 9.5px;
  font-weight: 550;
  text-align: left;
}

.preset-btn:hover {
  border-color: rgba(167, 139, 250, 0.4);
  background: rgba(167, 139, 250, 0.09);
  color: #fff;
}

.preset-btn .icon {
  width: 13px;
  height: 13px;
  color: var(--violet);
}

.tip-card {
  display: flex;
  gap: 8px;
  margin: 10px 9px 11px;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: linear-gradient(140deg, rgba(103, 232, 249, 0.055), rgba(167, 139, 250, 0.05));
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.55;
}

.tip-card > span {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  flex: none;
  border-radius: 6px;
  background: rgba(103, 232, 249, 0.1);
  color: var(--accent);
}

.tip-card .icon {
  width: 12px;
  height: 12px;
}

.tip-card p {
  margin: 0;
}

.tip-card strong {
  color: #c6d4e8;
}

.mobile-file-actions {
  display: none;
}

/* ---------------------------------------------------------------- viewport */

.viewport-wrap {
  position: relative;
  min-width: 0;
  min-height: 0;
}

.viewport {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #05070f;
  box-shadow: inset 0 0 80px rgba(0, 0, 0, 0.35);
}

.scene-canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100% !important;
  height: 100% !important;
  outline: none;
  touch-action: none;
}

.viewport-vignette {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(4, 7, 13, 0.45), transparent 18%, transparent 72%, rgba(3, 5, 10, 0.62)),
    radial-gradient(ellipse at 50% 44%, transparent 35%, rgba(2, 5, 10, 0.42) 100%);
}

.viewport-toolbar {
  position: absolute;
  top: 10px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 6px;
}

.tools-left {
  left: 10px;
}

.tools-right {
  right: 10px;
  left: auto;
}

.tool-group {
  display: flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid rgba(148, 163, 184, 0.17);
  border-radius: 10px;
  background: rgba(7, 11, 19, 0.78);
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(14px);
}

.tool-btn {
  display: flex;
  height: 31px;
  min-width: 31px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: var(--muted);
  font-size: 10px;
  font-weight: 550;
  white-space: nowrap;
}

.tool-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.tool-btn.active {
  border-color: rgba(103, 232, 249, 0.24);
  background: linear-gradient(180deg, rgba(103, 232, 249, 0.18), rgba(103, 232, 249, 0.09));
  color: var(--accent);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.tool-btn.wide {
  width: auto;
  padding: 0 9px;
  border-color: rgba(148, 163, 184, 0.17);
  border-radius: 10px;
  background: rgba(7, 11, 19, 0.78);
  backdrop-filter: blur(14px);
}

.tool-btn.wide.active {
  border-color: rgba(103, 232, 249, 0.35);
  background: rgba(103, 232, 249, 0.14);
  color: var(--accent);
}

.tool-btn .icon {
  width: 15px;
  height: 15px;
}

.tool-divider {
  width: 1px;
  height: 24px;
  margin: 0 1px;
  background: var(--line-strong);
}

.tool-group.compact {
  gap: 0;
}

.view-btn {
  min-width: 0;
  padding: 0 8px;
  font-size: 9.5px;
}

.viewport-footer {
  position: absolute;
  right: 12px;
  bottom: 10px;
  left: 12px;
  z-index: 3;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  pointer-events: none;
}

.viewport-hint {
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: 70%;
  padding: 5px 9px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  border-radius: 99px;
  background: rgba(6, 10, 18, 0.6);
  color: #8fa0ba;
  font-size: 9.5px;
  backdrop-filter: blur(10px);
}

.hint-dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 8px rgba(103, 232, 249, 0.9);
  animation: pulse-dot 2.6s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

.render-stats {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 7px;
  border: 1px solid rgba(148, 163, 184, 0.1);
  border-radius: 6px;
  background: rgba(6, 10, 18, 0.56);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8.5px;
  white-space: nowrap;
  backdrop-filter: blur(10px);
}

.badge-live {
  padding: 1px 4px;
  border: 1px solid rgba(103, 232, 249, 0.25);
  border-radius: 3px;
  color: var(--accent);
  font-size: 7.5px;
  letter-spacing: 0.08em;
}

.drop-overlay {
  position: absolute;
  inset: 0;
  z-index: 9;
  display: grid;
  place-items: center;
  background: rgba(3, 6, 12, 0.78);
  backdrop-filter: blur(8px);
}

.drop-overlay[hidden] {
  display: none;
}

.drop-card {
  display: flex;
  width: min(320px, 84%);
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 28px;
  border: 1px dashed rgba(103, 232, 249, 0.5);
  border-radius: 16px;
  background: rgba(103, 232, 249, 0.06);
  color: var(--accent);
  text-align: center;
}

.drop-card > span {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 12px;
  background: rgba(103, 232, 249, 0.12);
}

.drop-card .icon {
  width: 22px;
  height: 22px;
}

.drop-card h3 {
  margin: 6px 0 0;
  color: #e8fdff;
  font-size: 14px;
}

.drop-card p {
  margin: 0;
  color: #8fb7c2;
  font-size: 10.5px;
}

.record-hud {
  position: absolute;
  top: 56px;
  left: 50%;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 9px 8px 12px;
  border: 1px solid rgba(251, 113, 133, 0.42);
  border-radius: 10px;
  background: rgba(23, 8, 13, 0.9);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
  transform: translateX(-50%);
  backdrop-filter: blur(12px);
}

.record-hud[hidden] {
  display: none;
}

.record-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #fb7185;
  box-shadow: 0 0 9px rgba(251, 113, 133, 0.9);
  animation: rec-blink 1.2s steps(2, end) infinite;
}

@keyframes rec-blink {
  50% {
    opacity: 0.28;
  }
}

.record-hud strong {
  display: block;
  color: #ffd9df;
  font-size: 10px;
  letter-spacing: 0.04em;
}

.record-hud small {
  display: block;
  margin-top: 1px;
  color: #c08b96;
  font-family: var(--mono);
  font-size: 9px;
}

.loading-overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  background:
    radial-gradient(circle at 50% 44%, rgba(103, 232, 249, 0.07), transparent 30%),
    #05070f;
  transition: opacity 0.55s ease, visibility 0.55s;
}

.loading-overlay.is-hidden {
  visibility: hidden;
  opacity: 0;
}

.loading-overlay p {
  margin: 0;
  color: var(--muted-2);
  font-size: 10px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.loader-mark {
  position: relative;
  display: grid;
  width: 64px;
  height: 64px;
  place-items: center;
}

.loader-ring {
  position: absolute;
  inset: 0;
  border: 1px solid transparent;
  border-top-color: rgba(103, 232, 249, 0.8);
  border-right-color: rgba(167, 139, 250, 0.3);
  border-radius: 999px;
  animation: spin 1.1s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ---------------------------------------------------------------- inspector */

.inspector {
  padding-bottom: 20px;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 28px 20px 22px;
  text-align: center;
}

.empty-icon {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: linear-gradient(145deg, rgba(103, 232, 249, 0.08), rgba(167, 139, 250, 0.08));
  color: var(--accent);
}

.empty-icon .icon {
  width: 22px;
  height: 22px;
}

.empty-state h3 {
  margin: 2px 0 0;
  font-size: 12px;
  font-weight: 650;
}

.empty-state p {
  max-width: 220px;
  margin: 0;
  color: var(--muted-2);
  font-size: 10px;
  line-height: 1.55;
}

.inspector-hero {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px;
  border-bottom: 1px solid var(--line);
}

.inspector-hero .hero-icon {
  display: grid;
  width: 36px;
  height: 36px;
  flex: none;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: color-mix(in srgb, var(--node-color, #67e8f9) 12%, transparent);
  color: var(--node-color, var(--accent));
}

.inspector-hero .hero-icon .icon {
  width: 18px;
  height: 18px;
}

.inspector-hero .hero-copy {
  min-width: 0;
  flex: 1;
}

.hero-name {
  width: 100%;
  height: 26px;
  padding: 0 5px;
  border: 1px solid transparent;
  border-radius: 5px;
  outline: none;
  background: transparent;
  color: #f2f7ff;
  font-size: 12.5px;
  font-weight: 650;
}

.hero-name:hover {
  border-color: var(--line);
}

.hero-name:focus {
  border-color: rgba(103, 232, 249, 0.4);
  background: rgba(103, 232, 249, 0.05);
}

.hero-type {
  padding: 0 5px;
  color: var(--muted-2);
  font-size: 8.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.section {
  padding: 11px 13px 13px;
  border-bottom: 1px solid var(--line);
}

.section:last-child {
  border-bottom: 0;
}

.section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.section-head h3 {
  margin: 0;
  color: #a9b7cd;
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.section-action {
  padding: 2px 5px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--muted-2);
  font-size: 8.5px;
}

.section-action:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #dfe8f7;
}

.vector-field {
  margin-bottom: 7px;
}

.vector-field:last-child {
  margin-bottom: 0;
}

.vector-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted-2);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.vector-inputs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
}

.vec-input {
  position: relative;
  display: flex;
  align-items: center;
}

.vec-input .axis {
  position: absolute;
  left: 6px;
  z-index: 1;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  pointer-events: none;
}

.vec-input:nth-child(1) .axis {
  color: #fb7185;
}

.vec-input:nth-child(2) .axis {
  color: #6ee7b7;
}

.vec-input:nth-child(3) .axis {
  color: #93c5fd;
}

.vec-input input {
  width: 100%;
  height: 27px;
  padding: 0 5px 0 16px;
  border: 1px solid var(--line);
  border-radius: 5px;
  outline: none;
  background: rgba(4, 8, 15, 0.62);
  color: #d4dfef;
  font-family: var(--mono);
  font-size: 9.5px;
  font-variant-numeric: tabular-nums;
}

.vec-input input:focus {
  border-color: rgba(103, 232, 249, 0.48);
  background: rgba(103, 232, 249, 0.05);
}

.vec-input input:hover {
  border-color: var(--line-strong);
}

.vec-input input::-webkit-outer-spin-button,
.vec-input input::-webkit-inner-spin-button,
.num-input::-webkit-outer-spin-button,
.num-input::-webkit-inner-spin-button {
  margin: 0;
  -webkit-appearance: none;
}

.field-row {
  display: flex;
  min-height: 28px;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 5px;
}

.field-row > label {
  color: var(--muted);
  font-size: 10px;
}

.field-row .field-value {
  display: flex;
  align-items: center;
  gap: 5px;
}

.num-input,
.text-input,
.select-input {
  height: 27px;
  min-width: 0;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 5px;
  outline: none;
  background: rgba(4, 8, 15, 0.62);
  color: #d4dfef;
  font-family: var(--mono);
  font-size: 9.5px;
}

.num-input {
  width: 56px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.text-input,
.select-input {
  width: 132px;
  font-family: var(--font);
}

.num-input:focus,
.text-input:focus,
.select-input:focus {
  border-color: rgba(103, 232, 249, 0.48);
}

.range-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.range-row input[type="range"] {
  width: 100%;
  min-width: 0;
  height: 14px;
  margin: 0;
  accent-color: var(--accent);
}

.value-chip {
  min-width: 34px;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: rgba(4, 8, 15, 0.6);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  text-align: center;
}

.color-control {
  display: flex;
  align-items: center;
  gap: 6px;
}

.color-swatch {
  width: 26px;
  height: 26px;
  flex: none;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
}

.color-swatch input {
  width: 42px;
  height: 42px;
  margin: -8px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.color-hex {
  width: 72px;
  height: 27px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 5px;
  outline: none;
  background: rgba(4, 8, 15, 0.62);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  text-transform: uppercase;
}

.switch {
  position: relative;
  display: inline-flex;
  width: 30px;
  height: 17px;
  flex: none;
}

.switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.switch span {
  width: 100%;
  height: 100%;
  border: 1px solid var(--line-strong);
  border-radius: 99px;
  background: rgba(4, 8, 15, 0.7);
  transition: background 0.16s, border-color 0.16s;
}

.switch span::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 11px;
  height: 11px;
  border-radius: 99px;
  background: #64748b;
  content: "";
  transition: transform 0.16s, background 0.16s;
}

.switch input:checked + span {
  border-color: rgba(103, 232, 249, 0.55);
  background: rgba(103, 232, 249, 0.18);
}

.switch input:checked + span::after {
  background: var(--accent);
  box-shadow: 0 0 8px rgba(103, 232, 249, 0.55);
  transform: translateX(13px);
}

.inline-btn {
  height: 25px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.025);
  color: var(--muted);
  font-size: 8.5px;
}

.inline-btn:hover {
  border-color: var(--line-strong);
  color: #fff;
}

.key-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.key-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 24px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.02);
  color: var(--muted);
  font-size: 8.5px;
}

.key-chip:hover {
  border-color: rgba(103, 232, 249, 0.35);
  color: #fff;
}

.key-chip .dot {
  width: 5px;
  height: 5px;
  border-radius: 99px;
  background: var(--chip-color, var(--accent));
}

.key-chip.bump {
  animation: chip-bump 0.3s ease;
}

@keyframes chip-bump {
  50% {
    border-color: var(--accent);
    background: rgba(103, 232, 249, 0.12);
    transform: translateY(-1px);
  }
}

.preset-inline {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
  margin-top: 7px;
}

.empty-mini {
  padding: 8px;
  border: 1px dashed var(--line);
  border-radius: 6px;
  color: var(--muted-2);
  font-size: 9px;
  line-height: 1.5;
  text-align: center;
}

.bg-swatches {
  display: flex;
  gap: 5px;
  margin-top: 7px;
}

.bg-swatch {
  width: 24px;
  height: 20px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 5px;
}

.bg-swatch:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
}

.info-note {
  margin-top: 8px;
  padding: 7px 8px;
  border: 1px solid rgba(251, 191, 36, 0.16);
  border-radius: 6px;
  background: rgba(251, 191, 36, 0.05);
  color: #b9a374;
  font-size: 8.5px;
  line-height: 1.5;
}

/* ---------------------------------------------------------------- timeline */

.timeline {
  display: flex;
  flex: 0 0 248px;
  flex-direction: column;
  min-height: 0;
  margin: 8px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  backdrop-filter: blur(18px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.timeline-head {
  display: flex;
  min-height: 44px;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 5px 9px;
  border-bottom: 1px solid var(--line);
  overflow-x: auto;
  scrollbar-width: none;
}

.timeline-head::-webkit-scrollbar {
  display: none;
}

.transport,
.timeline-actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 4px;
}

.transport-btn {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
}

.transport-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.transport-btn .icon {
  width: 14px;
  height: 14px;
}

.play-btn {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  margin: 0 2px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #67e8f9, #b79bfc);
  color: #041018;
  box-shadow: 0 3px 16px rgba(103, 232, 249, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.play-btn:hover {
  filter: brightness(1.09);
}

.play-btn .icon {
  width: 16px;
  height: 16px;
}

.time-box {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin: 0 6px;
  padding: 2px 7px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: rgba(4, 8, 15, 0.5);
  white-space: nowrap;
}

.time-readout {
  color: #d8e6f5;
  font-family: var(--mono);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.time-total {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
}

.chip-toggle {
  display: inline-flex;
  height: 27px;
  align-items: center;
  gap: 4px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 99px;
  background: transparent;
  color: var(--muted);
  font-size: 9px;
  font-weight: 550;
  white-space: nowrap;
}

.chip-toggle .icon {
  width: 12px;
  height: 12px;
}

.chip-toggle:hover {
  border-color: var(--line-strong);
  color: #fff;
}

.chip-toggle.active {
  border-color: rgba(103, 232, 249, 0.34);
  background: rgba(103, 232, 249, 0.1);
  color: var(--accent);
}

.speed-field,
.ease-field {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--muted-2);
  font-size: 8px;
  white-space: nowrap;
}

.speed-field select,
.ease-field select {
  height: 26px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 5px;
  outline: none;
  background: rgba(4, 8, 15, 0.65);
  color: #b9c7da;
  font-family: var(--mono);
  font-size: 9px;
}

.ease-field select {
  width: 92px;
  font-family: var(--font);
}

.speed-field select:disabled,
.ease-field select:disabled {
  opacity: 0.4;
}

.key-btn {
  border-color: rgba(103, 232, 249, 0.26);
  background: rgba(103, 232, 249, 0.07);
  color: #bff8ff;
}

.key-btn:hover:not(:disabled) {
  background: rgba(103, 232, 249, 0.15);
  border-color: rgba(103, 232, 249, 0.45);
}

.key-btn .icon {
  width: 12px;
  height: 12px;
}

.timeline-zoom {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-left: 2px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
}

.timeline-settings {
  display: flex;
  min-height: 30px;
  flex: none;
  align-items: center;
  gap: 11px;
  padding: 0 12px;
  overflow-x: auto;
  border-bottom: 1px solid var(--line);
  color: var(--muted-2);
  font-size: 9px;
  scrollbar-width: none;
}

.timeline-settings::-webkit-scrollbar {
  display: none;
}

.timeline-settings label {
  display: flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.timeline-settings input[type="number"],
.timeline-settings select {
  height: 22px;
  padding: 0 3px;
  border: 1px solid var(--line);
  border-radius: 4px;
  outline: none;
  background: rgba(4, 8, 15, 0.5);
  color: #b9c7da;
  font-family: var(--mono);
  font-size: 8.5px;
}

.timeline-settings input[type="number"] {
  width: 47px;
  text-align: right;
}

.timeline-settings select {
  width: 44px;
}

.check-field input {
  width: 12px;
  height: 12px;
  accent-color: var(--accent);
}

.settings-sep {
  width: 1px;
  height: 13px;
  background: var(--line);
}

.timeline-tip {
  overflow: hidden;
  margin-left: auto;
  color: var(--muted-2);
  font-size: 8.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.timeline-main {
  display: grid;
  flex: 1;
  grid-template-columns: 142px minmax(0, 1fr);
  min-height: 0;
}

.track-labels {
  display: flex;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  border-right: 1px solid var(--line);
  background: rgba(4, 7, 13, 0.35);
}

.ruler-spacer {
  display: flex;
  height: 30px;
  flex: none;
  align-items: center;
  gap: 5px;
  overflow: hidden;
  padding: 0 10px;
  border-bottom: 1px solid var(--line);
  color: var(--muted-2);
  font-size: 8.5px;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.ruler-spacer .icon {
  width: 11px;
  height: 11px;
  color: var(--accent);
}

.ruler-spacer span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
}

.track-label-list {
  flex: 1;
  overflow: hidden;
}

.track-label-row {
  display: flex;
  height: 32px;
  align-items: center;
  gap: 6px;
  padding: 0 7px 0 11px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.065);
  color: var(--muted);
  font-size: 9.5px;
  user-select: none;
}

.track-label-row .track-dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 99px;
  background: var(--track-color, var(--accent));
  box-shadow: 0 0 6px color-mix(in srgb, var(--track-color, #67e8f9) 60%, transparent);
}

.track-label-row .track-name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.track-label-row .track-count {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7.5px;
}

.track-add {
  display: grid;
  width: 18px;
  height: 18px;
  flex: none;
  place-items: center;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--muted-2);
  opacity: 0;
}

.track-label-row:hover .track-add,
.track-label-row.has-keys .track-add {
  opacity: 1;
}

.track-add:hover {
  background: rgba(103, 232, 249, 0.13);
  color: var(--accent);
}

.track-add .icon {
  width: 10px;
  height: 10px;
}

.timeline-scroll {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: auto;
}

.timeline-inner {
  position: relative;
  min-width: 100%;
  height: 100%;
  min-height: 120px;
}

.ruler {
  position: sticky;
  top: 0;
  z-index: 5;
  height: 30px;
  border-bottom: 1px solid var(--line);
  background: rgba(6, 10, 18, 0.94);
  cursor: ew-resize;
  user-select: none;
}

.ruler-tick {
  position: absolute;
  top: 0;
  bottom: 0;
  border-left: 1px solid rgba(148, 163, 184, 0.1);
  pointer-events: none;
}

.ruler-tick.minor {
  top: 19px;
  border-color: rgba(148, 163, 184, 0.07);
}

.ruler-tick span {
  position: absolute;
  top: 7px;
  left: 4px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7.5px;
  white-space: nowrap;
}

.track-rows {
  position: relative;
  min-height: calc(100% - 30px);
}

.track-row {
  position: relative;
  height: 32px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.06);
  background: rgba(255, 255, 255, 0.006);
}

.track-row:nth-child(even) {
  background: rgba(255, 255, 255, 0.012);
}

.track-row:hover {
  background: rgba(103, 232, 249, 0.025);
}

.track-row .row-hit {
  position: absolute;
  inset: 0;
  cursor: crosshair;
}

.key-diamond {
  position: absolute;
  top: 50%;
  z-index: 3;
  width: 10px;
  height: 10px;
  padding: 0;
  border: 1.5px solid rgba(5, 8, 14, 0.9);
  border-radius: 2px;
  background: var(--key-color, var(--accent));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--key-color, #67e8f9) 35%, transparent);
  transform: translate(-50%, -50%) rotate(45deg);
  cursor: ew-resize;
  transition: box-shadow 0.12s, background 0.12s;
}

.key-diamond:hover {
  background: #fff;
  box-shadow: 0 0 10px var(--key-color, var(--accent));
}

.key-diamond.selected {
  background: #fff;
  box-shadow: 0 0 0 2px var(--key-color, var(--accent)), 0 0 12px var(--key-color, var(--accent));
}

.key-diamond.dragging {
  cursor: grabbing;
}

.playhead {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 6;
  width: 1px;
  background: rgba(103, 232, 249, 0.9);
  box-shadow: 0 0 8px rgba(103, 232, 249, 0.55);
  pointer-events: none;
}

.playhead-cap {
  position: absolute;
  top: 23px;
  left: -4px;
  width: 9px;
  height: 9px;
  border-radius: 2px;
  background: var(--accent);
  box-shadow: 0 0 10px rgba(103, 232, 249, 0.8);
  transform: rotate(45deg);
}

.track-empty {
  position: absolute;
  top: 30px;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  color: var(--muted-2);
  font-size: 9.5px;
  text-align: center;
  pointer-events: none;
}

.track-empty[hidden] {
  display: none;
}

.track-empty .icon {
  width: 18px;
  height: 18px;
  opacity: 0.45;
}

.track-empty p {
  margin: 0;
}

/* ---------------------------------------------------------------- toasts and modal */

.toasts {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 200;
  display: flex;
  max-width: min(340px, 88vw);
  flex-direction: column;
  gap: 7px;
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  background: rgba(10, 16, 27, 0.96);
  color: #cfdaeb;
  font-size: 10.5px;
  line-height: 1.45;
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
  animation: toast-in 0.22s ease-out;
  pointer-events: auto;
}

.toast .icon {
  width: 14px;
  height: 14px;
  margin-top: 1px;
  color: var(--accent);
}

.toast.success .icon {
  color: var(--green);
}

.toast.error {
  border-color: rgba(251, 113, 133, 0.35);
}

.toast.error .icon {
  color: var(--rose);
}

.toast.out {
  opacity: 0;
  transform: translateY(5px);
  transition: opacity 0.25s, transform 0.25s;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(7px);
  }
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 150;
  display: grid;
  place-items: center;
  padding: 18px;
  overflow: auto;
  background: rgba(2, 5, 10, 0.72);
  backdrop-filter: blur(10px);
  animation: fade-in 0.18s ease-out;
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
}

.modal {
  width: min(720px, 100%);
  max-height: 90dvh;
  overflow: auto;
  padding: 21px;
  border: 1px solid var(--line-strong);
  border-radius: 16px;
  background:
    radial-gradient(600px 250px at 10% -10%, rgba(103, 232, 249, 0.06), transparent 60%),
    #0a101b;
  box-shadow: 0 26px 80px rgba(0, 0, 0, 0.6);
  animation: modal-in 0.22s ease-out;
}

@keyframes modal-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.985);
  }
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.modal-head h2 {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.modal-head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.5;
}

.modal-close {
  display: grid;
  width: 30px;
  height: 30px;
  flex: none;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}

.modal-close:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.template-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.template-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.018);
  text-align: left;
}

.template-card:hover {
  border-color: rgba(103, 232, 249, 0.42);
  transform: translateY(-1px);
}

.template-thumb {
  position: relative;
  height: 92px;
  overflow: hidden;
  background: #05070f;
}

.template-thumb::before,
.template-thumb::after {
  position: absolute;
  content: "";
}

.template-thumb.empty::before {
  inset: 18px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  background-image: linear-gradient(rgba(148, 163, 184, 0.09) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.09) 1px, transparent 1px);
  background-size: 12px 12px;
  transform: perspective(90px) rotateX(48deg);
}

.template-thumb.neon {
  background: radial-gradient(circle at 50% 58%, rgba(139, 92, 246, 0.5), transparent 36%), #060913;
}

.template-thumb.neon::before {
  top: 25px;
  left: 50%;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: radial-gradient(circle at 35% 30%, #c4b5fd, #7c3aed 45%, #2e1065);
  box-shadow: 0 0 24px rgba(139, 92, 246, 0.8);
  transform: translateX(-50%);
}

.template-thumb.neon::after {
  top: 19px;
  left: 50%;
  width: 64px;
  height: 40px;
  border: 1px solid rgba(34, 211, 238, 0.75);
  border-radius: 50%;
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.3);
  transform: translateX(-50%) rotate(-15deg);
}

.template-thumb.showcase {
  background: radial-gradient(circle at 50% 62%, rgba(245, 199, 106, 0.18), transparent 40%), #08070d;
}

.template-thumb.showcase::before {
  bottom: 22px;
  left: 50%;
  width: 24px;
  height: 44px;
  border-radius: 4px 4px 2px 2px;
  background: linear-gradient(90deg, #c9bda9, #fdf7ea 45%, #ac9f8b);
  box-shadow: 0 0 20px rgba(245, 199, 106, 0.18);
  transform: translateX(-50%);
}

.template-thumb.showcase::after {
  bottom: 13px;
  left: 50%;
  width: 66px;
  height: 14px;
  border-radius: 50%;
  background: #131522;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.6);
  transform: translateX(-50%);
}

.template-meta {
  padding: 8px 9px 10px;
}

.template-meta strong {
  display: block;
  font-size: 11px;
  font-weight: 650;
}

.template-meta small {
  display: block;
  margin-top: 2px;
  color: var(--muted-2);
  font-size: 8.5px;
  line-height: 1.4;
}

.help-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 20px;
}

.help-block h3 {
  margin: 0 0 7px;
  color: #b6c4d8;
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.help-block p {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.6;
}

.shortcut-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.shortcut-list div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 5px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.07);
  color: var(--muted);
  font-size: 9.5px;
}

.shortcut-list div:last-child {
  border-bottom: 0;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 7px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.about-line {
  margin-top: 14px;
  color: var(--muted-2);
  font-size: 8.5px;
  line-height: 1.5;
  text-align: center;
}

/* ---------------------------------------------------------------- responsive */

.mobile-only {
  display: none !important;
}

@media (max-width: 1240px) {
  .workspace {
    grid-template-columns: 232px minmax(0, 1fr) 276px;
  }

  .brand-tag {
    display: none;
  }

  .project-name {
    width: min(240px, 24vw);
  }

  .chip-toggle span:last-child {
    display: none;
  }

  .chip-toggle {
    padding: 0 7px;
  }
}

@media (max-width: 1080px) {
  .top-actions .btn:not(.icon-btn):not(.primary) {
    padding: 0 8px;
  }

  .workspace {
    grid-template-columns: 214px minmax(0, 1fr) 258px;
  }

  .timeline {
    flex-basis: 240px;
  }

  .speed-field,
  .ease-field {
    display: none;
  }
}

@media (max-width: 920px) {
  .mobile-only {
    display: inline-flex !important;
  }

  .workspace {
    display: block;
    position: relative;
    padding: 6px 6px 0;
  }

  .viewport-wrap {
    position: absolute;
    inset: 6px 6px 0;
  }

  .panel {
    position: fixed;
    top: 64px;
    bottom: 8px;
    z-index: 90;
    width: min(320px, 88vw);
    box-shadow: 0 22px 70px rgba(0, 0, 0, 0.6);
    transition: transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1);
  }

  .panel-left {
    left: 8px;
    transform: translateX(calc(-100% - 16px));
  }

  .panel-right {
    right: 8px;
    transform: translateX(calc(100% + 16px));
  }

  .panel.is-open {
    transform: translateX(0);
  }

  .panel-left .panel-head,
  .panel-right .panel-head {
    padding-top: 10px;
  }

  .drawer-backdrop {
    position: fixed;
    inset: 0;
    z-index: 80;
    background: rgba(2, 5, 10, 0.58);
    backdrop-filter: blur(3px);
  }

  .drawer-backdrop[hidden] {
    display: none;
  }

  .timeline {
    flex-basis: 236px;
    margin: 6px;
  }

  .timeline-main {
    grid-template-columns: 112px minmax(0, 1fr);
  }

  .mobile-file-actions {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 5px;
    margin: 8px 9px 0;
  }

  .mobile-file-actions .btn {
