  }

  #newBtn,
  #openBtn,
  #saveBtn {
    display: none;
  }

  .btn {
    height: 32px;
    padding: 0 9px;
  }

  .btn.icon-btn {
    width: 32px;
  }

  .top-actions .btn.primary {
    padding: 0 10px;
    font-size: 10.5px;
  }

  .timeline {
    flex-basis: 224px;
  }

  .timeline-head {
    padding: 4px 7px;
  }

  .timeline-actions {
    gap: 3px;
  }

  .timeline-actions .ease-field,
  .timeline-zoom {
    display: none;
  }

  .timeline-settings {
    gap: 8px;
    padding: 0 8px;
  }

  .timeline-tip {
    display: none;
  }

  .timeline-main {
    grid-template-columns: 96px minmax(0, 1fr);
  }

  .track-label-row {
    padding-left: 8px;
  }

  .track-label-row .track-count {
    display: none;
  }

  .tools-right .view-btn {
