  }

  .template-grid {
    grid-template-columns: 1fr;
  }

  .template-card {
    flex-direction: row;
  }

  .template-thumb {
    width: 120px;
    height: 78px;
    flex: none;
  }

  .help-grid {
    grid-template-columns: 1fr;
  }

  .modal {
    padding: 16px;
  }

  .toasts {
    right: 8px;
    bottom: 8px;
    left: 8px;
    max-width: none;
  }

  .timeline {
    margin: 5px 6px 6px;
  }
}

@media (max-width: 460px) {
  .top-actions .btn.primary {
    padding: 0 8px;
  }

  #exportCaret {
    display: none;
  }

  .time-box {
    margin: 0 2px;
    padding: 2px 5px;
  }

  .time-readout {
