+            <div><span>Salvar / Abrir</span><span><kbd>Ctrl</kbd>+<kbd>S</kbd> <kbd>Ctrl</kbd>+<kbd>O</kbd></span></div>
+            <div><span>Duplicar / Excluir</span><span><kbd>Ctrl</kbd>+<kbd>D</kbd> <kbd>Del</kbd></span></div>
